-- Isolated role identities; every fixture and workflow write is rolled back.
create temporary table tc_coord_qa(result jsonb);
do $$
declare co uuid:=gen_random_uuid();oc uuid:=gen_random_uuid();p uuid:=gen_random_uuid();pm uuid:=gen_random_uuid();ae uuid:=gen_random_uuid();sub_ uuid:=gen_random_uuid();owner_ uuid:=gen_random_uuid();lender uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();req uuid:=gen_random_uuid();action_req uuid:=gen_random_uuid();r jsonb;s jsonb;retry jsonb;payload jsonb;rid uuid;sid uuid;nid uuid;c integer;checks integer:=0;denied boolean;
begin
 begin
 insert into auth.users(id,email) select x,x::text||'@qa.invalid' from unnest(array[pm,ae,sub_,owner_,lender,outsider]) x;
 insert into public.profiles(id,role,active) values(pm,'pm',true),(ae,'architect',true),(sub_,'subcontractor',true),(owner_,'owner',true),(lender,'lender',true),(outsider,'admin',true) on conflict(id) do update set role=excluded.role,active=true;
 insert into public.companies(id,name) values(co,'Transient coordination QA'),(oc,'Other transient coordination QA');
 insert into public.projects(id,company_id,name) values(p,co,'Transient coordination project');
 insert into public.project_members(project_id,user_id,role,active) values(p,pm,'pm',true),(p,ae,'architect',true),(p,sub_,'subcontractor',true),(p,owner_,'owner',true),(p,lender,'lender',true);
 insert into public.company_users(company_id,user_id,active) values(oc,outsider,true);
 insert into public.rfis(project_id,rfi_no,subject,question,created_by) values(p,'RFI-999','Legacy','Legacy question',pm);
 perform set_config('request.jwt.claim.sub',pm::text,true);
 execute 'set local role authenticated';
 payload:=jsonb_build_object('title','Detail conflict','text','Please clarify','assignee',ae,'drawingRef','A101','specRef','01 00','dueAt','2026-12-01T12:00:00Z');
 r:=public.tc_coord_create(p,'rfi',req,payload);rid:=(r->'record'->>'id')::uuid;
 if r->'record'->>'rfi_no'<>'RFI-1000' or r->'record'->>'drawing_reference'<>'A101' then raise exception 'Numbering/fields not saved';end if;checks:=checks+1;
 retry:=public.tc_coord_create(p,'rfi',req,payload);if retry->'record'->>'id'<>rid::text or jsonb_array_length(retry->'events')<>1 then raise exception 'Create retry duplicated';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_create(p,'rfi',req,payload||'{"text":"Changed"}');exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Changed retry accepted';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_action('rfi',rid,1,'respond',gen_random_uuid(),'{"text":"Wrong actor"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Wrong responder accepted';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_action('rfi',rid,1,'close',gen_random_uuid(),'{"text":"Premature"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Unanswered record closed';end if;checks:=checks+1;
 denied:=false;begin update public.rfis set status='closed' where id=rid;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Direct write accepted';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',ae::text,true);
 select id into nid from public.tc_coord_notifications where record_id=rid;if nid is null then raise exception 'Assignment notification absent';end if;checks:=checks+1;
 perform public.tc_coord_read_notification(nid);
 if not exists(select 1 from public.tc_coord_notifications where id=nid and read_at is not null) then raise exception 'Notification not marked read';end if;checks:=checks+1;
 r:=public.tc_coord_action('rfi',rid,1,'respond',action_req,'{"text":"Use detail 4"}');if r->'record'->>'status'<>'answered' then raise exception 'Response not saved';end if;checks:=checks+1;
 retry:=public.tc_coord_action('rfi',rid,1,'respond',action_req,'{"text":"Use detail 4"}');if jsonb_array_length(retry->'events')<>2 then raise exception 'Action retry duplicated';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',pm::text,true);
 denied:=false;begin perform public.tc_coord_read_notification(nid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Other recipient marked read';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_action('rfi',rid,1,'comment',gen_random_uuid(),'{"text":"Stale"}');exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Stale action accepted';end if;checks:=checks+1;
 r:=public.tc_coord_action('rfi',rid,2,'close',gen_random_uuid(),'{"text":"Resolved"}');
 denied:=false;begin perform public.tc_coord_action('rfi',rid,3,'comment',gen_random_uuid(),'{"text":"Closed"}');exception when check_violation then denied:=true;end;if not denied then raise exception 'Closed comment accepted';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',ae::text,true);denied:=false;begin perform public.tc_coord_action('rfi',rid,3,'reopen',gen_random_uuid(),'{"text":"Unauthorized reopen"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Reviewer reopened record';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',pm::text,true);r:=public.tc_coord_action('rfi',rid,3,'reopen',gen_random_uuid(),'{"text":"New information"}');if r->'record'->>'status'<>'open' then raise exception 'Reopen failed';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',sub_::text,true);
 select count(*) into c from public.rfis where project_id=p;if c<>0 then raise exception 'Unrelated subcontractor sees RFIs';end if;checks:=checks+1;
 s:=public.tc_coord_create(p,'submittal',gen_random_uuid(),jsonb_build_object('title','Product data','text','Initial submission','assignee',ae,'requiredOnSite','2026-12-15'));sid:=(s->'record'->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',ae::text,true);
 s:=public.tc_coord_action('submittal',sid,1,'review',gen_random_uuid(),'{"text":"Revise finish","disposition":"revise_resubmit"}');if s->'record'->>'status'<>'revise_resubmit' then raise exception 'Review failed';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',sub_::text,true);
 s:=public.tc_coord_action('submittal',sid,2,'resubmit',gen_random_uuid(),jsonb_build_object('text','Corrected finish','assignee',ae));if s->'record'->>'revision_no'<>'1' or s->'record'->>'status'<>'resubmitted' then raise exception 'Revision failed';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',ae::text,true);
 s:=public.tc_coord_action('submittal',sid,3,'review',gen_random_uuid(),'{"text":"Proceed with notes","disposition":"approved_as_noted"}');if s->'record'->>'status'<>'reviewed' then raise exception 'Approval failed';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',pm::text,true);s:=public.tc_coord_action('submittal',sid,4,'close',gen_random_uuid(),'{"text":"Review completed"}');if s->'record'->>'status'<>'closed' then raise exception 'Close failed';end if;checks:=checks+1;
 denied:=false;begin update public.submittal_events set comments='Rewrite' where submittal_id=sid;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Audit editable';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',owner_::text,true);r:=public.tc_coord_detail('rfi',rid);if (r->'capabilities'->>'manage')::boolean then raise exception 'Owner gained manager';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_coord_create(p,'rfi',gen_random_uuid(),'{"title":"No","text":"No"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Owner created without grant';end if;checks:=checks+1;
 select count(*) into c from public.tc_coord_notifications where project_id=p;if c<>0 then raise exception 'Owner sees other recipients';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',lender::text,true);denied:=false;begin perform public.tc_coord_list(p,'rfi');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Lender list accessible';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',outsider::text,true);denied:=false;begin perform public.tc_coord_detail('rfi',rid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Other company admin accessed';end if;checks:=checks+1;
 execute 'set local role postgres';update public.profiles set active=false where id=ae;
 perform set_config('request.jwt.claim.sub',ae::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.tc_coord_detail('submittal',sid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Inactive user retained access';end if;checks:=checks+1;
 execute 'set local role postgres';
 raise exception using errcode='ZQ003',message='Rollback fixtures';
 exception when sqlstate 'ZQ003' then null;
 end;
 if exists(select 1 from auth.users where id=pm) or exists(select 1 from public.companies where id=co) then raise exception 'Fixtures persisted';end if;
 insert into tc_coord_qa values(jsonb_build_object('status','PASS','checks',checks,'fixture_rolled_back',true));
end $$;
select result from tc_coord_qa;
